 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Repeated tiles are separated by all-zero gutters. Detect topmost/leftmost
    # motif run, then use its width and the intervening zero gap as the period.
    def runs(vals):
        spans=[]; i=0
        while i<len(vals):
            if vals[i]==0: i+=1; continue
            a=i
            while i<len(vals) and vals[i]!=0: i+=1
            spans.append((a,i))
        return spans
    rs=[]
    for r in range(h):
        x=runs(grid[r])
        if len(x)>=2: rs=x; break
    cs=[]
    for c in range(w):
        x=runs([grid[r][c] for r in range(h)])
        if len(x)>=2: cs=x; break
    if not rs or not cs: return out
    # Tile center tracks are the centers of the detected nonzero runs.
    rowcent=[(a+b-1)//2 for a,b in rs]
    colcent=[(a+b-1)//2 for a,b in cs]
    # At each intersection, read the color of the interior center.
    colors={(r,c):grid[r][c] for r in rowcent for c in colcent if r<h and c<w and grid[r][c]!=0}
    for r in rowcent:
        for col in set(colors[(r,c)] for c in colcent if (r,c) in colors):
            xs=[c for c in colcent if colors.get((r,c))==col]
            for a,b in zip(xs,xs[1:]):
                for c in range(a+1,b):
                    if grid[r][c]==0: out[r][c]=col
    for c in colcent:
        for col in set(colors[(r,c)] for r in rowcent if (r,c) in colors):
            ys=[r for r in rowcent if colors.get((r,c))==col]
            for a,b in zip(ys,ys[1:]):
                for r in range(a+1,b):
                    if grid[r][c]==0: out[r][c]=col
    return out
