from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    tiles=[]
    for r in range(h-4):
        for c in range(w-4):
            if all(grid[r][c+j]==grid[r+4][c+j]==4 for j in range(5)) and all(grid[r+i][c]==grid[r+i][c+4]==4 for i in range(5)):
                v=grid[r+2][c+2]
                if v not in (0,4) and all(grid[y][x]==v for y in range(r+1,r+4) for x in range(c+1,c+4)):
                    tiles.append((r+2,c+2,v))
    counts=Counter(v for _,_,v in tiles)
    if not counts:return out
    high=max(counts.values())
    points=[p for p in tiles if counts[p[2]]<high]
    for r,c,v in points:
        for rr,cc,vv in points:
            if v!=vv:continue
            if rr==r and cc>c:
                for x in range(c+1,cc):
                    if grid[r][x]==0:out[r][x]=v
            elif cc==c and rr>r:
                for y in range(r+1,rr):
                    if grid[y][c]==0:out[y][c]=v
    return out
